@SpringBootTest @ActiveProfiles("test") @Transactional
class PerformanceCommitmentWorkflowIntegrationTest {
 @Autowired PerformanceCommitmentService commitments; @Autowired PerformanceCommitmentWorkflowService workflow;
 @Autowired PerformancePolicyRepository policyRoots; @Autowired PerformancePolicyVersionRepository policyVersions;
 @Autowired PerformanceRatingScaleRepository scaleRoots; @Autowired PerformanceRatingScaleVersionRepository scaleVersions;
 @Autowired PerformanceSuccessIndicatorRepository indicatorRoots; @Autowired PerformanceSuccessIndicatorVersionRepository indicatorVersions;
 @Autowired PerformanceTemplateRepository templateRoots; @Autowired PerformanceTemplateVersionRepository templateVersions;
 @Autowired PerformanceTemplateSectionRepository templateSections; @Autowired PerformanceTemplateItemRepository templateItems;
 @Autowired PerformanceCycleRepository cycles; @Autowired PerformanceCycleMilestoneRepository milestones;
 @Autowired PerformancePlanAssignmentRepository assignments;
 @MockBean HumanResourcePerformanceParticipantClient humanResource; @MockBean AdministrativePerformancePlanningClient administrative;

 @BeforeEach void sources(){when(humanResource.get(anyLong(),anyString())).thenAnswer(x->person(x.getArgument(0)));when(humanResource.getByEmployeeNo(anyString(),anyString())).thenAnswer(x->person(Long.parseLong(((String)x.getArgument(0)).substring(2))));when(administrative.membership(anyLong(),anyString())).thenAnswer(x->membership(x.getArgument(0)));when(administrative.organization(eq("BUSINESS_UNIT"),anyLong(),anyString())).thenReturn(new AdministrativePerformancePlanningClient.OrganizationTarget("BUSINESS_UNIT",5L,"UNIT","Unit",7L,"Area","o".repeat(64),Instant.now()));when(administrative.approvalRoute(eq(5L),eq("PERFORMANCE_INDIVIDUAL_COMMITMENT"),anyString())).thenReturn(route(101L,102L));}

 @Test void exactSequentialRouteApprovesIdempotentlyAndFreezesTheCommitment(){Fixture f=fixture("WORKFLOW-A",10L);CommitmentResponse draft=target(f,"E-10");WorkflowResponse submitted=workflow.submit(f.agency(),draft.id(),command(draft,null,"submit-1",null),"Bearer x","E-10",PermissionDataScope.OWN_RECORDS,null);assertThat(submitted.commitment().status()).isEqualTo("SUBMITTED");assertThat(submitted.routes()).singleElement().satisfies(r->{assertThat(r.routeRevision()).isOne();assertThat(r.steps()).extracting(StepResponse::actionType).containsExactly("RECOMMEND","APPROVE");assertThat(r.steps()).extracting(StepResponse::status).containsExactly("CURRENT","PENDING");});assertThatThrownBy(()->workflow.recommend(f.agency(),draft.id(),command(submitted.commitment(),1,"wrong","ok"),"Bearer x","E-999",null)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);WorkflowResponse recommended=workflow.recommend(f.agency(),draft.id(),command(submitted.commitment(),1,"recommend-1","Reviewed"),"Bearer x","E-101",null);assertThat(recommended.commitment().status()).isEqualTo("IN_REVIEW");WorkflowResponse retry=workflow.recommend(f.agency(),draft.id(),command(submitted.commitment(),1,"recommend-1","Reviewed"),"Bearer x","E-101",null);assertThat(retry.actions()).extracting(ActionResponse::requestKey).contains("recommend-1");WorkflowResponse approved=workflow.approve(f.agency(),draft.id(),command(recommended.commitment(),1,"approve-1","Approved"),"Bearer x","E-102",null);assertThat(approved.commitment().status()).isEqualTo("APPROVED");assertThat(approved.routes().get(0).status()).isEqualTo("COMPLETED");assertThat(approved.actions()).extracting(ActionResponse::type).containsExactly("SUBMIT","RECOMMEND","APPROVE");TargetInput target=targetInput(approved.commitment());assertThatThrownBy(()->commitments.replaceTargets(f.agency(),draft.id(),new TargetReplacement(approved.commitment().recordVersion(),List.of(target)),"Bearer x","E-10",PermissionDataScope.OWN_RECORDS,null)).hasMessageContaining("draft");}

 @Test void returnResubmitAndPreDecisionRouteRebasePreserveHistory(){Fixture f=fixture("WORKFLOW-B",20L);CommitmentResponse draft=target(f,"E-20");WorkflowResponse submitted=workflow.submit(f.agency(),draft.id(),command(draft,null,"submit-1",null),"Bearer x","E-20",PermissionDataScope.OWN_RECORDS,null);WorkflowResponse returned=workflow.returnForChanges(f.agency(),draft.id(),command(submitted.commitment(),1,"return-1","Clarify targets"),"Bearer x","E-101",null);assertThat(returned.commitment().status()).isEqualTo("RETURNED");CommitmentResponse edited=commitments.replaceTargets(f.agency(),draft.id(),new TargetReplacement(returned.commitment().recordVersion(),List.of(targetInput(returned.commitment()))),"Bearer x","E-20",PermissionDataScope.OWN_RECORDS,null);WorkflowResponse resubmitted=workflow.submit(f.agency(),draft.id(),command(edited,null,"submit-2",null),"Bearer x","E-20",PermissionDataScope.OWN_RECORDS,null);assertThat(resubmitted.routes()).extracting(RouteResponse::routeRevision).containsExactly(1,2);assertThat(resubmitted.actions()).extracting(ActionResponse::type).containsExactly("SUBMIT","RETURN","RESUBMIT");WorkflowResponse rebased=workflow.rebase(f.agency(),draft.id(),command(resubmitted.commitment(),2,"rebase-1","Administrative route refreshed"),"Bearer x","HR-ADMIN",null);assertThat(rebased.routes()).extracting(RouteResponse::routeRevision).containsExactly(1,2,3);assertThat(rebased.commitment().lifecycleRevision()).isGreaterThan(resubmitted.commitment().lifecycleRevision());}

 @Test void selfFinalApprovalRouteFailsClosedWithoutSubmission(){when(administrative.approvalRoute(eq(5L),eq("PERFORMANCE_INDIVIDUAL_COMMITMENT"),anyString())).thenReturn(route(101L,30L));Fixture f=fixture("WORKFLOW-C",30L);CommitmentResponse draft=target(f,"E-30");assertThatThrownBy(()->workflow.submit(f.agency(),draft.id(),command(draft,null,"submit-self",null),"Bearer x","E-30",PermissionDataScope.OWN_RECORDS,null)).hasMessageContaining("cannot finally approve");assertThat(commitments.get(f.agency(),draft.id(),"E-30",PermissionDataScope.OWN_RECORDS).status()).isEqualTo("DRAFT");}

 @Test void approvedAmendmentCopiesTheExactPlanAndSupersedesOnlyAfterSuccessorApproval(){Fixture f=fixture("WORKFLOW-D",40L);CommitmentResponse draft=target(f,"E-40");WorkflowResponse submitted=workflow.submit(f.agency(),draft.id(),command(draft,null,"submit-original",null),"Bearer x","E-40",PermissionDataScope.OWN_RECORDS,null);WorkflowResponse recommended=workflow.recommend(f.agency(),draft.id(),command(submitted.commitment(),1,"recommend-original","Reviewed"),"Bearer x","E-101",null);WorkflowResponse approved=workflow.approve(f.agency(),draft.id(),command(recommended.commitment(),1,"approve-original","Approved"),"Bearer x","E-102",null);CommitmentResponse amendment=commitments.amend(f.agency(),draft.id(),new AmendmentCommand(approved.commitment().recordVersion(),"amend-1","Correct target wording"),"HR-ADMIN",PermissionDataScope.AGENCY_WIDE,null);assertThat(amendment.status()).isEqualTo("AMENDMENT_DRAFT");assertThat(amendment.supersedesId()).isEqualTo(draft.id());assertThat(amendment.sections().get(0).items().get(0).committedValue()).isEqualByComparingTo("25");assertThat(commitments.get(f.agency(),draft.id(),"HR-ADMIN",PermissionDataScope.AGENCY_WIDE).status()).isEqualTo("APPROVED");assertThat(commitments.amend(f.agency(),draft.id(),new AmendmentCommand(approved.commitment().recordVersion(),"amend-1","Correct target wording"),"HR-ADMIN",PermissionDataScope.AGENCY_WIDE,null).id()).isEqualTo(amendment.id());WorkflowResponse amendmentSubmitted=workflow.submit(f.agency(),amendment.id(),command(amendment,null,"submit-amendment",null),"Bearer x","E-40",PermissionDataScope.OWN_RECORDS,null);WorkflowResponse amendmentRecommended=workflow.recommend(f.agency(),amendment.id(),command(amendmentSubmitted.commitment(),1,"recommend-amendment","Reviewed"),"Bearer x","E-101",null);workflow.approve(f.agency(),amendment.id(),command(amendmentRecommended.commitment(),1,"approve-amendment","Approved"),"Bearer x","E-102",null);assertThat(commitments.get(f.agency(),draft.id(),"HR-ADMIN",PermissionDataScope.AGENCY_WIDE).status()).isEqualTo("SUPERSEDED");}

 @Test void assignedTaskFilteringExposesOnlyTheCurrentExactReviewer(){Fixture f=fixture("WORKFLOW-SCOPE",50L);CommitmentResponse draft=target(f,"E-50");WorkflowResponse submitted=workflow.submit(f.agency(),draft.id(),command(draft,null,"submit-scope",null),"Bearer x","E-50",PermissionDataScope.OWN_RECORDS,null);CommitmentFilter inbox=new CommitmentFilter("IPCR",null,null,null,null,null,true);assertThat(commitments.list(f.agency(),"E-101",PermissionDataScope.ASSIGNED_RECORDS,inbox)).extracting(CommitmentResponse::id).containsExactly(draft.id());assertThat(commitments.list(f.agency(),"E-102",PermissionDataScope.ASSIGNED_RECORDS,inbox)).isEmpty();workflow.recommend(f.agency(),draft.id(),command(submitted.commitment(),1,"recommend-scope","Reviewed"),"Bearer x","E-101",null);assertThat(commitments.list(f.agency(),"E-102",PermissionDataScope.ASSIGNED_RECORDS,inbox)).extracting(CommitmentResponse::id).containsExactly(draft.id());assertThatThrownBy(()->commitments.get(f.agency(),draft.id(),"UNRELATED",PermissionDataScope.ASSIGNED_RECORDS)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}

 private CommitmentResponse target(Fixture f,String actor){CommitmentResponse draft=commitments.generate(f.agency(),f.assignment().getId(),"generate-1",actor,PermissionDataScope.OWN_RECORDS,null);return commitments.replaceTargets(f.agency(),draft.id(),new TargetReplacement(draft.recordVersion(),List.of(targetInput(draft))),"Bearer x",actor,PermissionDataScope.OWN_RECORDS,null);}
 private static TargetInput targetInput(CommitmentResponse response){ItemResponse item=response.sections().get(0).items().get(0);return new TargetInput(item.id(),new BigDecimal("25"),null,null,LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"Expected output",null,"Plan","MOV");}
 private static Command command(CommitmentResponse c,Integer route,String key,String reason){return new Command(c.recordVersion(),c.contentRevision(),c.lifecycleRevision(),route,key,reason,false,null);}
 private static HumanResourceAssessmentSubject person(Long id){return new HumanResourceAssessmentSubject(id,"E-"+id,"Employee "+id,true,1000L+id,LocalDateTime.of(2025,1,1,8,0),2000L+id,3000L+id,"p".repeat(64),LocalDateTime.now(),Instant.now());}
 private static AdministrativePerformancePlanningClient.PersonnelMembership membership(Long id){return new AdministrativePerformancePlanningClient.PersonnelMembership(id,5L,"UNIT","Unit",7L,"Area",false,false,"MAIN","o".repeat(64),Instant.now());}
 private static AdministrativePerformancePlanningClient.ApprovalRoute route(Long first,Long last){return new AdministrativePerformancePlanningClient.ApprovalRoute(1L,"PERFORMANCE_INDIVIDUAL_COMMITMENT",2,5L,7L,List.of(new AdministrativePerformancePlanningClient.ApprovalRouteStep(11L,1,first),new AdministrativePerformancePlanningClient.ApprovalRouteStep(12L,2,last)),"r".repeat(64),Instant.now());}

 private Fixture fixture(String agency,Long employee){PerformancePolicy pr=policyRoots.saveAndFlush(new PerformancePolicy(agency,"P"));PerformancePolicyVersion policy=policyVersions.saveAndFlush(new PerformancePolicyVersion(agency,pr.getId(),1,null,"Policy",null,"Basis","SPMS",PerformancePolicyVersion.Frequency.ANNUAL,false,false,false,false,false));policy.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());policy=policyVersions.saveAndFlush(policy);PerformanceRatingScale sr=scaleRoots.saveAndFlush(new PerformanceRatingScale(agency,"S"));PerformanceRatingScaleVersion scale=scaleVersions.saveAndFlush(new PerformanceRatingScaleVersion(agency,sr.getId(),policy.getId(),1,null,"Scale",null,"Basis",BigDecimal.ONE,new BigDecimal("5"),2,RoundingMode.HALF_UP,PerformanceRatingScaleVersion.MeasureType.NUMBER,PerformanceRatingScaleVersion.Direction.HIGHER_IS_BETTER,PerformanceRatingScaleVersion.DimensionScoreSource.THRESHOLD_BAND));scale.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());scale=scaleVersions.saveAndFlush(scale);PerformanceSuccessIndicator ir=indicatorRoots.saveAndFlush(new PerformanceSuccessIndicator(agency,"I"));PerformanceSuccessIndicatorVersion indicator=indicatorVersions.saveAndFlush(new PerformanceSuccessIndicatorVersion(agency,ir.getId(),policy.getId(),scale.getId(),1,null,"Indicator",null,"Output","KRA","KPI","Success",PerformanceRatingScaleVersion.MeasureType.NUMBER,"count",PerformanceRatingScaleVersion.Direction.HIGHER_IS_BETTER,BigDecimal.TEN,null,null,true,"MOV"));indicator.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());indicator=indicatorVersions.saveAndFlush(indicator);PerformanceTemplate tr=templateRoots.saveAndFlush(new PerformanceTemplate(agency,"IPCR"));PerformanceTemplateVersion template=templateVersions.saveAndFlush(new PerformanceTemplateVersion(agency,tr.getId(),policy.getId(),scale.getId(),1,null,"IPCR",null,PerformanceTemplateVersion.FormType.IPCR,"Individual Commitment","Basis"));PerformanceTemplateSection section=templateSections.saveAndFlush(new PerformanceTemplateSection(agency,template.getId(),PerformanceTemplateSection.Type.CORE,"CORE","Core",null,new BigDecimal("100.0000"),1));templateItems.saveAndFlush(new PerformanceTemplateItem(agency,section.getId(),indicator.getId(),null,new BigDecimal("100.0000"),true,null,1));template.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());template=templateVersions.saveAndFlush(template);PerformanceCycle cycle=cycles.saveAndFlush(new PerformanceCycle(agency,"C","Cycle",LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),policy.getId(),"Asia/Manila"));milestones.saveAll(List.of(new PerformanceCycleMilestone(agency,cycle.getId(),PerformanceCycleMilestone.Type.PLANNING_OPEN,"PLANNING_OPEN","Planning opens",Instant.parse("2026-01-01T00:00:00Z"),null,true,1,null,false),new PerformanceCycleMilestone(agency,cycle.getId(),PerformanceCycleMilestone.Type.PLANNING_DUE,"PLANNING_DUE","Planning due",Instant.parse("2026-12-01T00:00:00Z"),Instant.parse("2026-12-15T00:00:00Z"),true,2,null,false),new PerformanceCycleMilestone(agency,cycle.getId(),PerformanceCycleMilestone.Type.APPROVAL_DUE,"APPROVAL_DUE","Approval due",Instant.parse("2026-12-16T00:00:00Z"),Instant.parse("2026-12-31T00:00:00Z"),true,3,null,false)));cycle.open("test","open",Instant.now());cycle=cycles.saveAndFlush(cycle);String no="E-"+employee;PerformancePlanAssignment assignment=assignments.saveAndFlush(new PerformancePlanAssignment(agency,cycle.getId(),template.getId(),PerformancePlanAssignment.SubjectType.EMPLOYEE,employee,no,"Employee",7L,"Area",5L,"Unit",employee,no,"Employee",1000L+employee,2000L+employee,3000L+employee,"IPCR","o".repeat(64),"p".repeat(64),"r".repeat(64)));assignment.activate("test","activate",Instant.now());assignment=assignments.saveAndFlush(assignment);return new Fixture(agency,assignment);}
 private record Fixture(String agency,PerformancePlanAssignment assignment){}
}
